package tw.com.tft.documentscanner.imaging;import android.graphics.Bitmap;import org.opencv.android.Utils;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import java.util.*;public final class DocumentDetector{public static class Result{public final float[] corners;public final double confidence;public final boolean fallback;Result(float[]c,double f,boolean b){corners=c;confidence=f;fallback=b;}}private static class C{Point[]p;double s;C(Point[]p,double s){this.p=p;this.s=s;}}public static Result detect(Bitmap b){Mat rgba=new Mat();Utils.bitmapToMat(b,rgba);Mat rgb=new Mat();Imgproc.cvtColor(rgba,rgb,Imgproc.COLOR_RGBA2RGB);rgba.release();Mat gray=new Mat();Imgproc.cvtColor(rgb,gray,Imgproc.COLOR_RGB2GRAY);Mat blur=new Mat();Imgproc.GaussianBlur(gray,blur,new Size(5,5),0);List<Mat> masks=new ArrayList<>();for(double[]t:new double[][]{{45,135},{75,210}}){Mat e=new Mat();Imgproc.Canny(blur,e,t[0],t[1],3,true);masks.add(e);}Mat a=new Mat();Imgproc.adaptiveThreshold(blur,a,255,Imgproc.ADAPTIVE_THRESH_GAUSSIAN_C,Imgproc.THRESH_BINARY_INV,31,9);masks.add(a);Mat o=new Mat();Imgproc.threshold(blur,o,0,255,Imgproc.THRESH_BINARY_INV|Imgproc.THRESH_OTSU);masks.add(o);Mat hsv=new Mat();Imgproc.cvtColor(rgb,hsv,Imgproc.COLOR_RGB2HSV);Mat pm=new Mat();Core.inRange(hsv,new Scalar(0,0,105),new Scalar(180,125,255),pm);masks.add(pm);hsv.release();List<C> cs=new ArrayList<>();Mat k=Imgproc.getStructuringElement(Imgproc.MORPH_RECT,new Size(7,7));double ia=rgb.cols()*(double)rgb.rows();for(Mat raw:masks){Mat m=new Mat();Imgproc.morphologyEx(raw,m,Imgproc.MORPH_CLOSE,k,new Point(-1,-1),2);List<MatOfPoint> cont=new ArrayList<>();Mat h=new Mat();Imgproc.findContours(m,cont,h,Imgproc.RETR_LIST,Imgproc.CHAIN_APPROX_SIMPLE);h.release();m.release();for(MatOfPoint co:cont){double ar=Math.abs(Imgproc.contourArea(co)),rat=ar/ia;if(rat<.18||rat>.98){co.release();continue;}MatOfPoint2f c2=new MatOfPoint2f(co.toArray());double per=Imgproc.arcLength(c2,true);for(double ep:new double[]{.012,.02,.035}){MatOfPoint2f ap=new MatOfPoint2f();Imgproc.approxPolyDP(c2,ap,ep*per,true);Point[]p=ap.toArray();if(p.length==4){MatOfPoint q=new MatOfPoint(p);if(Imgproc.isContourConvex(q)){Point[]ord=order(p);double s=score(ord,ar,ia,gray);if(s>0)cs.add(new C(ord,s));}q.release();}ap.release();}c2.release();co.release();}raw.release();}k.release();C best=null;for(C c:cs)if(best==null||c.s>best.s)best=c;float[]r;double conf;boolean fb;if(best!=null&&best.s>=.56){r=norm(best.p,rgb.cols(),rgb.rows());conf=Math.min(.99,best.s);fb=false;}else{r=safeInset();conf=.25;fb=true;}blur.release();gray.release();rgb.release();return new Result(r,conf,fb);}private static double score(Point[]p,double ar,double ia,Mat g){double rat=ar/ia;MatOfPoint2f mp=new MatOfPoint2f(p);RotatedRect rr=Imgproc.minAreaRect(mp);mp.release();double rect=Math.min(1,ar/Math.max(1,rr.size.area()));double cx=0,cy=0;for(Point x:p){cx+=x.x;cy+=x.y;}cx/=4;cy/=4;double center=Math.max(0,1-.6*Math.hypot(Math.abs(cx-g.cols()/2.0)/(g.cols()/2.0),Math.abs(cy-g.rows()/2.0)/(g.rows()/2.0)));Mat mask=Mat.zeros(g.size(),CvType.CV_8UC1);MatOfPoint poly=new MatOfPoint(p);Imgproc.fillConvexPoly(mask,poly,new Scalar(255));double bright=Math.max(0,Math.min(1,(Core.mean(g,mask).val[0]-85)/150.0));poly.release();mask.release();double s=.36*Math.min(1,rat/.72)+.24*rect+.16*center+.12*bright+.12;if(rat>.38)s+=.06;return s;}private static Point[] order(Point[]p){Point[]o=new Point[4];double mins=1e30,maxs=-1e30,mind=1e30,maxd=-1e30;for(Point x:p){double s=x.x+x.y,d=x.y-x.x;if(s<mins){mins=s;o[0]=x;}if(s>maxs){maxs=s;o[2]=x;}if(d<mind){mind=d;o[1]=x;}if(d>maxd){maxd=d;o[3]=x;}}return o;}private static float[] norm(Point[]p,int w,int h){float[]f=new float[8];for(int i=0;i<4;i++){f[i*2]=cl((float)(p[i].x/w));f[i*2+1]=cl((float)(p[i].y/h));}return f;}private static float cl(float v){return Math.max(.01f,Math.min(.99f,v));}public static float[] safeInset(){return new float[]{.05f,.05f,.95f,.05f,.95f,.95f,.05f,.95f};}}